style.css:
@-moz-document domain("mail.google.com"), url-prefix("https://mail.google.com/") {
/* General Background */
    body, .aeF, .nH, .bkK, .bq3, .brg, .nH .apV, .nH .ain, .nH .aia {
        background-color: #fce4ec !important; /* Blush pink */
        color: #5a5a5a !important; /* Neutral text */
    }

    /* Sidebar and Header Backgrounds */
    .gb_Fa, .gb_3, .gb_nc, .gb_lc, .LrBjie {
        background-color: #f8e3eb !important; /* Light blush pink */
        color: #ec9ec0 !important; /* Accent pink */
    }

    /* Email List Items */
    .zA {
        background-color: #f8e3eb !important; /* Blush pink for emails */
        border-bottom: 1px solid #f3dce5 !important; /* Subtle border */
    }

    .zA:hover {
        background-color: #fcd9e6 !important; /* Slightly deeper pink on hover */
    }

    /* Unread Emails */
    .zE {
        background-color: #f9d8e2 !important; /* Slightly darker pink for unread */
        color: #ec9ec0 !important; /* Pink text for unread emails */
        font-weight: bold !important;
    }

    /* Top Search Bar */
    .gb_Xf {
        background-color: #fde6ef !important; /* Blush pink input area */
        border: 1px solid #ec9ec0 !important; /* Accent border */
        color: #5a5a5a !important;
    }

    .gb_Xf:hover, .gb_Xf:focus {
        background-color: #fce4ec !important; /* White-pink hover */
        border-color: #d78ba9 !important; /* Stronger border */
    }

    /* Compose Button */
    .z0 {
        background-color: #ec9ec0 !important;
        color: white !important;
        font-weight: bold !important;
        border-radius: 50px !important;
        padding: 10px 20px !important;
    }

    .z0:hover {
        background-color: #d78ba9 !important;
    }

    /* Labels and Sidebar Text */
    .TO, .aKz, .aKw, .aim, .wT, .aqs {
        background-color: #fde6ef !important; /* Light blush pink */
        color: #5a5a5a !important; /* Text in neutral gray */
        border-radius: 5px !important;
    }

    /* Borders and Dividers */
    .nH, .bq3, .LrBjie {
        border-color: #f8e3eb !important;
    }

    /* Google Chat - Pink Theme */
    .WYZmif {
        background-color: #f8e3eb !important; /* Light blush pink for Google Chat */
        color: #5a5a5a !important; /* Neutral text color */
    }

    .yMlI0e {
        background-color: #fce4ec !important; /* Blush pink for chat bubbles */
    }

    .gb_Pg {
        background-color: #ec9ec0 !important; /* Accent pink for send button */
        color: white !important;
    }

    .gb_Pg:hover {
        background-color: #d78ba9 !important; /* Darker pink on hover */
    }

    /* Hover Effects */
    .T-I:hover, .T-I-J3:hover {
        background-color: #d78ba9 !important; /* Slightly deeper pink */
        border-color: #c46c91 !important;
    }
}
